	SET_OPEN_TITLE = "Öffenbares",
	SET_OPEN_DESC = "Zeigt einen beweglichen Button (mit Anzahl + Liste) für öffenbare Taschengegenstände — Horte, Schatztruhen, Beutel, Questbehälter. Klick zum Öffnen.",
